
// AGUARDAR O CARREGAMENTO DA PÁGINA
document.addEventListener("DOMContentLoaded", () => {

    // CURTIR PUBLICAÇÕES
        const likeButtons = document.querySelectorAll(".like-button");

            likeButtons.forEach(button => {

                    button.addEventListener("click", () => {

                                const article = button.closest("article");
                                            const likesCount = article.querySelector(".likes-count");
                                                        const icon = button.querySelector("i");

                                                                    let likes = parseInt(
                                                                                    likesCount.textContent.replace(/\D/g, "")
                                                                                                );

                                                                                                            if (button.classList.contains("liked")) {

                                                                                                                            button.classList.remove("liked");

                                                                                                                                            icon.classList.remove("bxs-heart");
                                                                                                                                                            icon.classList.add("bx-heart");

                                                                                                                                                                            likes--;

                                                                                                                                                                                        } else {

                                                                                                                                                                                                        button.classList.add("liked");

                                                                                                                                                                                                                        icon.classList.remove("bx-heart");
                                                                                                                                                                                                                                        icon.classList.add("bxs-heart");

                                                                                                                                                                                                                                                        likes++;

                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                likesCount.textContent =
                                                                                                                                                                                                                                                                                                likes.toLocaleString("pt-BR") + " curtidas";

                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                            });


                                                                                                                                                                                                                                                                                                                // SALVAR PUBLICAÇÕES
                                                                                                                                                                                                                                                                                                                    const saveButtons = document.querySelectorAll(
                                                                                                                                                                                                                                                                                                                            'button[aria-label="Salvar publicação"]'
                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                    saveButtons.forEach(button => {

                                                                                                                                                                                                                                                                                                                                            button.addEventListener("click", () => {

                                                                                                                                                                                                                                                                                                                                                        const icon = button.querySelector("i");

                                                                                                                                                                                                                                                                                                                                                                    icon.classList.toggle("bxs-bookmark");
                                                                                                                                                                                                                                                                                                                                                                                icon.classList.toggle("bx-bookmark");

                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                            });


                                                                                                                                                                                                                                                                                                                                                                                                // BOTÃO SEGUIR
                                                                                                                                                                                                                                                                                                                                                                                                    const followButtons = document.querySelectorAll("aside button");

                                                                                                                                                                                                                                                                                                                                                                                                        followButtons.forEach(button => {

                                                                                                                                                                                                                                                                                                                                                                                                                if (button.textContent.trim() === "Seguir") {

                                                                                                                                                                                                                                                                                                                                                                                                                            button.addEventListener("click", () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                            if (button.textContent.trim() === "Seguir") {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.textContent = "Seguindo";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    button.classList.remove("text-blue-500");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.classList.add("text-gray-500");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.textContent = "Seguir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.classList.remove("text-gray-500");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    button.classList.add("text-blue-500");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // BOTÃO DE COMENTÁRIOS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const commentButtons = document.querySelectorAll(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'button[aria-label="Comentar"]'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    commentButtons.forEach(button => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.addEventListener("click", () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const article = button.closest("article");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const username = article.querySelector(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "header h2"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ).textContent;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Você está visualizando os comentários de " + username);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // BOTÃO DE COMPARTILHAR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const shareButtons = document.querySelectorAll(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'button[aria-label="Compartilhar"]'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                shareButtons.forEach(button => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.addEventListener("click", async () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const article = button.closest("article");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const username = article.querySelector(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "header h2"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ).textContent;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const shareData = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        title: "Publicação do Instagram",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        text: "Confira esta publicação de " + username,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        url: window.location.href
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (navigator.share) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await navigator.share(shareData);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else if (navigator.clipboard) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await navigator.clipboard.writeText(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                shareData.url
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Link copiado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Compartilhamento não disponível.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (error.name !== "AbortError") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Não foi possível compartilhar.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // MENSAGEM DE INICIALIZAÇÃO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Clone Instagram carregado com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            